exports.scheduledDailyBackup = onSchedule({
    schedule: "0 2 * * *",
    region: "me-central1",
    timeZone: "Asia/Kuwait"
}, async (event) => {
    const schoolsSnap = await db.collection("schools").get();

    for (const schoolDoc of schoolsSnap.docs) {
        const schoolId = schoolDoc.id;
        const backupData = {};
        const collections = ["students", "attendance", "behavior", "warnings"];

        for (const col of collections) {
            const snap = await db.collection(col).where("schoolId", "==", schoolId).limit(1000).get();
            backupData[col] = snap.size;
        }

        await db.collection("backups").add({
            schoolId: schoolId,
            type: "scheduled",
            summary: backupData,
            createdAt: admin.firestore.FieldValue.serverTimestamp()
        });
    }

    console.log("Daily backup completed for all schools");
    return null;
});
