exports.archiveYearSafe = onCall({
    cors: [/bo3li1993\.github\.io$/, /localhost/],
    region: "me-central1"
}, async (request) => {
    if (!request.auth) throw new HttpsError("unauthenticated", "ط·آ¸ط¸آ¹ط·آ·ط¢آ¬ط·آ·ط¢آ¨ ط·آ·ط¹آ¾ط·آ·ط¢آ³ط·آ·ط¢آ¬ط·آ¸ط¸آ¹ط·آ¸أ¢â‚¬â€چ ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ·ط¢آ¯ط·آ·ط¢آ®ط·آ¸ط«â€ ط·آ¸أ¢â‚¬â€چ");

    const adminDoc = await db.collection("users").doc(request.auth.uid).get();
    if (!adminDoc.exists || !["admin", "superadmin"].includes(adminDoc.data().role)) {
        throw new HttpsError("permission-denied", "ط·آ·ط¢آ§ط·آ¸أ¢â‚¬â€چط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ¯ط·آ¸ط¸آ¹ط·آ·ط¢آ± ط·آ¸ط¸آ¾ط·آ¸أ¢â‚¬ع‘ط·آ·ط¢آ·");
    }

    const { year } = request.data;
    const schoolId = adminDoc.data().role === "superadmin" 
        ? request.data.schoolId 
        : adminDoc.data().schoolId;

    if (!year || !schoolId) throw new HttpsError("invalid-argument", "year ط·آ¸ط«â€  schoolId ط·آ¸أ¢â‚¬آ¦ط·آ·ط¢آ·ط·آ¸أ¢â‚¬â€چط·آ¸ط«â€ ط·آ·ط¢آ¨ط·آ·ط¢آ§ط·آ¸أ¢â‚¬آ ");

    const fromDate = year + "-01-01";
    const toDate = year + "-12-31";
    const collections = ["attendance", "behavior", "warnings"];
    let totalArchived = 0;

    for (const col of collections) {
        const snap = await db.collection(col)
            .where("schoolId", "==", schoolId)
            .where("date", ">=", fromDate)
            .where("date", "<=", toDate)
            .get();

        const ops = snap.docs.map(function(doc) {
            return {
                type: "set",
                ref: db.collection("archive_" + col).doc(year + "_" + doc.id),
                data: { ...doc.data(), archivedYear: year, archivedAt: admin.firestore.FieldValue.serverTimestamp() }
            };
        });

        const archived = await commitInBatches(ops);
        totalArchived += archived;
        console.log("Archived", archived, "records from", col);
    }

    await db.collection("audit_log").add({
        schoolId,
        action: "archive_year",
        year,
        recordsArchived: totalArchived,
        performedBy: adminDoc.data().name || request.auth.uid,
        createdAt: admin.firestore.FieldValue.serverTimestamp()
    });

    return { success: true, archived: totalArchived, message: "ط·آ·ط¹آ¾ط·آ¸أ¢â‚¬آ¦ ط·آ·ط¢آ£ط·آ·ط¢آ±ط·آ·ط¢آ´ط·آ¸ط¸آ¾ط·آ·ط¢آ© " + totalArchived + " ط·آ·ط¢آ³ط·آ·ط¢آ¬ط·آ¸أ¢â‚¬â€چ" };
});

