exports.addStudentIdsSafe = onCall({
    cors: [/bo3li1993\.github\.io$/, /localhost/],
    region: "me-central1"
}, async (request) => {
    if (!request.auth || request.auth.uid !== "superadmin") {
        throw new HttpsError("permission-denied", "Super Admin ط·آ¸ط¸آ¾ط·آ¸أ¢â‚¬ع‘ط·آ·ط¢آ·");
    }

    const studentsSnap = await db.collection("students").get();
    
    const ops = studentsSnap.docs
        .filter(function(doc) { return !doc.data().studentId; })
        .map(function(doc) {
            return {
                type: "update",
                ref: doc.ref,
                data: { studentId: "STU-" + doc.id.substring(0, 8).toUpperCase() }
            };
        });

    const updated = await commitInBatches(ops);
    return { success: true, updated };
});
