// FUNCTION: generateReportNowSecure أ¢â‚¬â€‌ ط·ع¾ط¸â€ڑط·آ±ط¸ظ¹ط·آ± ط¸ظ¾ط¸ث†ط·آ±ط¸ظ¹ ط¸â€¦ط·آ­ط¸â€¦ط¸ظ¹
// أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯
exports.generateReportNowSecure = onCall({
    cors: [/bo3li1993\.github\.io$/, /localhost/],
    region: "me-central1"
}, async (request) => {
    const userData = await requireAuth(request, ["admin", "assistant_manager", "superadmin"]);
    const schoolId = userData.role === "superadmin" ? request.data.schoolId : userData.schoolId;

    const { fromDate, toDate, monthLabel } = request.data;
    if (!schoolId || !fromDate || !toDate) {
        throw new HttpsError("invalid-argument", "ط·آ¬ط¸â€¦ط¸ظ¹ط·آ¹ ط·آ§ط¸â€‍ط·آ­ط¸â€ڑط¸ث†ط¸â€‍ ط¸â€¦ط·آ·ط¸â€‍ط¸ث†ط·آ¨ط·آ©");
    }

    const [absSnap, behavSnap, warnSnap] = await Promise.all([
        db.collection("attendance").where("schoolId","==",schoolId).where("status","==","absent").where("date",">=",fromDate).where("date","<=",toDate).get(),
        db.collection("behavior").where("schoolId","==",schoolId).where("date",">=",fromDate).where("date","<=",toDate).get(),
        db.collection("warnings").where("schoolId","==",schoolId).where("date",">=",fromDate).where("date","<=",toDate).get()
    ]);

    return {
        absences: absSnap.size,
        behavior: behavSnap.size,
        warnings: warnSnap.size,
        period: monthLabel || (fromDate + " أ¢â‚¬â€‌ " + toDate)
    };
});

// أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯
// FUNCTION: promoteStudentsSecure أ¢â‚¬â€‌ ط·ع¾ط·آ±ط¸â€ڑط¸ظ¹ط·آ© ط·آ§ط¸â€‍ط·آ·ط¸â€‍ط·آ§ط·آ¨ ط¸â€¦ط·آ­ط¸â€¦ط¸ظ¹ط·آ©
// أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯أ¢â€¢ع¯
exports.promoteStudentsSecure = onCall({
    cors: [/bo3li1993\.github\.io$/, /localhost/],
    region: "me-central1"
}, async (request) => {
    const userData = await requireAuth(request, ["admin", "superadmin"]);
    const schoolId = userData.schoolId;

    const { promotionMap } = request.data;
    if (!promotionMap || typeof promotionMap !== "object") {
        throw new HttpsError("invalid-argument", "promotionMap ط¸â€¦ط·آ·ط¸â€‍ط¸ث†ط·آ¨");
    }

    const studentsSnap = await db.collection("students")
        .where("schoolId", "==", schoolId).get();

    const ops = [];
    studentsSnap.docs.forEach(function(doc) {
        var student = doc.data();
        var newClass = promotionMap[student.classId];
        if (newClass) {
            ops.push({ type: "update", ref: doc.ref, data: { classId: newClass } });
        }
    });

    let promoted = 0;
    const BATCH_SIZE = 450;
    for (let i = 0; i < ops.length; i += BATCH_SIZE) {
        const batch = db.batch();
        ops.slice(i, i + BATCH_SIZE).forEach(function(op) {
            batch.update(op.ref, op.data);
        });
        await batch.commit();
        promoted += Math.min(BATCH_SIZE, ops.length - i);
    }

    await db.collection("audit_log").add({
        schoolId,
        action: "promote_students",
        recordsUpdated: promoted,
        performedBy: userData.name || request.auth.uid,
        createdAt: admin.firestore.FieldValue.serverTimestamp()
    });

    return { success: true, promoted };
});

