exports.saveFcmTokenSecure = onCall({
    cors: [/bo3li1993\.github\.io$/, /localhost/],
    region: "me-central1"
}, async (request) => {
    if (!request.auth || !request.auth.uid) {
        throw new HttpsError("unauthenticated", "ط¸ظ¹ط·آ¬ط·آ¨ ط·ع¾ط·آ³ط·آ¬ط¸ظ¹ط¸â€‍ ط·آ§ط¸â€‍ط·آ¯ط·آ®ط¸ث†ط¸â€‍");
    }

    const { token } = request.data;
    if (!token) throw new HttpsError("invalid-argument", "token ط¸â€¦ط·آ·ط¸â€‍ط¸ث†ط·آ¨");

    await db.collection("users").doc(request.auth.uid).update({
        fcmToken: token,
        fcmUpdatedAt: admin.firestore.FieldValue.serverTimestamp()
    });

    return { success: true };
});

