exports.askAiAssistantSecure = onCall({
    cors: [/bo3li1993\.github\.io$/, /localhost/],
    region: "me-central1"
}, async (request) => {
    const userData = await requireAuth(request, ["admin", "assistant_manager", "superadmin"]);

    const { prompt } = request.data;
    if (!prompt || prompt.length > 500) {
        throw new HttpsError("invalid-argument", "prompt ط¸â€¦ط·آ·ط¸â€‍ط¸ث†ط·آ¨ ط¸ث†ط¸â€‍ط·آ§ ط¸ظ¹ط·ع¾ط·آ¬ط·آ§ط¸ث†ط·آ² 500 ط·آ­ط·آ±ط¸ظ¾");
    }

    // ط·ع¾ط·آ³ط·آ¬ط¸ظ¹ط¸â€‍ ط·آ§ط¸â€‍ط·آ§ط·آ³ط·ع¾ط·آ®ط·آ¯ط·آ§ط¸â€¦
    await db.collection("audit_log").add({
        schoolId: userData.schoolId,
        action: "ai_assistant_query",
        performedBy: userData.name || request.auth.uid,
        createdAt: admin.firestore.FieldValue.serverTimestamp()
    });

    return { 
        success: true, 
        message: "ط·ع¾ط¸â€¦ ط·آ§ط·آ³ط·ع¾ط¸â€ڑط·آ¨ط·آ§ط¸â€‍ ط·آ³ط·آ¤ط·آ§ط¸â€‍ط¸ئ’: " + prompt.substring(0, 50) + "..."
    };
});
