// Rate Limiting محسّن - IP + userId + device
// ════════════════════════════════════════════════════════════════
async function checkRateLimitAdvanced(userId, ipAddress) {
    const now = Date.now();
    const LOCKOUT_MS = LOCKOUT_MINUTES * 60 * 1000;

    // تحقق من userId
    const userRef = db.collection("login_attempts").doc("user_" + userId);
    const userSnap = await userRef.get();

    if (userSnap.exists) {
        const data = userSnap.data();
        const lastAttempt = data.lastAttempt?.toMillis ? data.lastAttempt.toMillis() : 0;
        const minutesSince = (now - lastAttempt) / 60000;

        if (data.count >= MAX_ATTEMPTS && minutesSince < LOCKOUT_MINUTES) {
            return { locked: true, remaining: Math.ceil(LOCKOUT_MINUTES - minutesSince), reason: "user" };
        }
    }

    // تحقق من IP
    if (ipAddress) {
        const ipKey = "ip_" + ipAddress.replace(/\./g, "_").replace(/:/g, "_");
        const ipRef = db.collection("login_attempts").doc(ipKey);
        const ipSnap = await ipRef.get();

        if (ipSnap.exists) {
            const data = ipSnap.data();
            const lastAttempt = data.lastAttempt?.toMillis ? data.lastAttempt.toMillis() : 0;
            const minutesSince = (now - lastAttempt) / 60000;

            // IP يُغلق بعد 20 محاولة فاشلة
            if (data.count >= 20 && minutesSince < LOCKOUT_MINUTES) {
                return { locked: true, remaining: Math.ceil(LOCKOUT_MINUTES - minutesSince), reason: "ip" };
            }
        }
    }

    return { locked: false };
}

async function recordFailedAttemptAdvanced(userId, ipAddress) {
    const batch = db.batch();

    // سجّل فشل userId
    const userRef = db.collection("login_attempts").doc("user_" + userId);
    const userSnap = await userRef.get();
    const userCount = userSnap.exists ? (userSnap.data().count || 0) + 1 : 1;
    batch.set(userRef, { count: userCount, lastAttempt: admin.firestore.FieldValue.serverTimestamp() });

    // سجّل فشل IP
    if (ipAddress) {
        const ipKey = "ip_" + ipAddress.replace(/\./g, "_").replace(/:/g, "_");
        const ipRef = db.collection("login_attempts").doc(ipKey);
        const ipSnap = await ipRef.get();
        const ipCount = ipSnap.exists ? (ipSnap.data().count || 0) + 1 : 1;
        batch.set(ipRef, { count: ipCount, lastAttempt: admin.firestore.FieldValue.serverTimestamp() });
    }

    await batch.commit();
}